```java
import java.io.*;
import java.util.*;

public class CommandExecutor {
    public void runSystemCommand(String userInput) throws IOException {
        // To fix this, we avoid passing a raw string to a shell.
        // Instead, we use ProcessBuilder with a list of arguments.
        // This treats 'userInput' strictly as a single argument rather than part of a command string.
        List<String> command = new ArrayList<>();
        command.add("ls");
        command.add(userInput); // Even if this contains ";", it will be treated as a literal filename

        ProcessBuilder processBuilder = new ProcessBuilder(command);
        // Redirect error stream to simplify reading output
        processBuilder.redirectErrorStream(true);

        Process process = processBuilder.start();

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }
    }
}
```

